BEGIN;
SET ROLE air_repository_owner;
ALTER TABLE reporting.course_current_catalog_api ADD COLUMN IF NOT EXISTS college_name text;
ALTER TABLE reporting.course_current_catalog_api ADD COLUMN IF NOT EXISTS department_name text;
ALTER TABLE reporting.course_catalog_detail_api ADD COLUMN IF NOT EXISTS department_name text;
DELETE FROM reporting.course_current_catalog_api;
INSERT INTO reporting.course_current_catalog_api (course_id,university_course_id,course_code,course_title,source_system_code,report_refresh_run_id,report_as_of_utc,college_name,department_name) SELECT c.course_id,c.university_course_id,c.course_code,c.course_title,c.source_system_code,c.report_refresh_run_id,c.report_as_of_utc,d.college_name,r.department_name FROM reporting.course_current_catalog c LEFT JOIN reporting.course_catalog_detail d ON d.course_id=c.course_id LEFT JOIN reporting.course_organization_reconciliation r ON r.university_course_id=c.university_course_id;
DELETE FROM reporting.course_catalog_detail_api;
INSERT INTO reporting.course_catalog_detail_api (course_id,university_course_id,course_code,course_title,college_name,course_description,course_goals,course_learning_outcomes,department_name) SELECT d.course_id,d.university_course_id,d.course_code,d.course_title,d.college_name,d.course_description,d.course_goals,d.course_learning_outcomes,r.department_name FROM reporting.course_catalog_detail d LEFT JOIN reporting.course_organization_reconciliation r ON r.university_course_id=d.university_course_id;
COMMIT;
